tool_input_args.value:
awk -F',' 'NR>1 && $7=="won" {
  total+=$5; count++;
  rep[$2]+=$5; rep_count[$2]++;
  prod[$4]+=$5; prod_count[$4]++;
  region[$3]+=$5; region_count[$3]++;
}
END {
  printf "=== TOTAL WON DEALS ===\n";
  printf "Deals: %d | Total New Contract Value: $%\047d\n\n", count, total;

  printf "=== BY REP ===\n";
  for (r in rep) printf "  %-20s %2d deals  $%\047d\n", r, rep_count[r], rep[r];

  printf "\n=== BY PRODUCT ===\n";
  for (p in prod) printf "  %-28s %2d deals  $%\047d\n", p, prod_count[p], prod[p];

  printf "\n=== BY REGION ===\n";
  for (g in region) printf "  %-10s %2d deals  $%\047d\n", g, region_count[g], region[g];
}' /workspace/data/sales_q3.csv
